/**
 * Copies every live issue of a project into another project, for
 * `ProjectService.cloneProject`. Unlike `copyIssuesToProject`, this is a
 * fresh start: archived issues are left behind, numbering restarts at 1 in
 * source-number order, and everything that records progress — status,
 * assignee, start/completion time — is reset. Comments, attachments and
 * parent links are never copied. Returns the new rows, in copy order.
 */
export async function cloneLiveIssuesToProject(
  orgId: OrgId,
  fromProjectId: ProjectId,
  toProjectId: ProjectId,
  authorId: UserId,
  defaultStatus: IssueStatus,
): Promise<readonly Issue[]> {
  const db = getDb();

  const sourceRows = db
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, fromProjectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(issues.number)
    .all();

  if (sourceRows.length === 0) return [];

  const labels = await listLabelsForIssues(
    orgId,
    sourceRows.map((row) => row.id as IssueId),
  );

  const stamp = toIsoTimestamp(new Date());
