  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertCan(actor, "project:create", orgResource(input.orgId));
  assertNotArchived("Project", source.id, source);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const usedProjects = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", usedProjects)) {
    throw new Error(
      `Plan ${org.plan} allows ${usedProjects} projects; upgrade to add another`,
    );
  }

  const issuesToCopy = input.includeIssues
    ? await issueRepo.countIssues(input.orgId, source.id)
    : 0;

  if (
    issuesToCopy > 0 &&
    wouldExceedLimit(org.plan, "issuesPerProject", 0, issuesToCopy)
  ) {
    throw new Error(
      `Plan ${org.plan} cannot fit ${issuesToCopy} issues in a cloned project`,
    );
  }

  const project = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug: input.slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  const copiedIssues = input.includeIssues
    ? await issueRepo.cloneLiveIssuesToProject(
        input.orgId,
        source.id,
        project.id,
        actor.userId,
        org.settings.defaultIssueStatus as IssueStatus,
      )
    : [];

  await indexProject(input.orgId, project);
  for (const issue of copiedIssues) {
    await indexIssue(input.orgId, issue);
  }
  await usageRepo.incrementUsage(input.orgId, {
    projectsUsed: 1,
    issuesUsed: copiedIssues.length,
  });

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied: copiedIssues.length,
  });

  return project;
}

